function movesToMakeZigzag(nums) {
  const moves = [0, 0];
  for (let i = 0; i < nums.length; i++) {
    const left = i > 0 ? nums[i - 1] : Infinity;
    const right = i + 1 < nums.length ? nums[i + 1] : Infinity;
    const lowest = Math.min(left, right);
    if (nums[i] >= lowest) {
      moves[i % 2] += nums[i] - lowest + 1;
    }
  }
  return Math.min(moves[0], moves[1]);
}

