function movesToMakeZigzag(nums) {
  // Simulate one move at a time: while some adjacent pair breaks the pattern, lower the side that must be smaller.
  const costFor = (peakParity) => {
    const a = nums.slice();
    let count = 0;
    for (;;) {
      let fixed = false;
      for (let i = 0; i + 1 < a.length && !fixed; i++) {
        const small = i % 2 === peakParity ? i + 1 : i;
        const big = small === i ? i + 1 : i;
        if (a[small] >= a[big]) { a[small]--; count++; fixed = true; }
      }
      if (!fixed) return count;
    }
  };
  return Math.min(costFor(0), costFor(1));
}

